SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `his_db` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `his_db`;

DROP TABLE IF EXISTS `patients`;

CREATE TABLE `patients` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `patient_name` VARCHAR(50) DEFAULT NULL,
  `id_card_no` CHAR(18) DEFAULT NULL,
  `household_addr` VARCHAR(500) DEFAULT NULL,
  `mi_account_no` BIGINT DEFAULT NULL,
  `his_patient_id` VARCHAR(20) DEFAULT NULL,
  `insurance_type` VARCHAR(32) DEFAULT NULL,
  `phone_no` VARCHAR(20) DEFAULT NULL,
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_deleted` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_id_card_no` (`id_card_no`),
  KEY `idx_mi_account_no` (`mi_account_no`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

LOCK TABLES `patients` WRITE;
ALTER TABLE `patients` DISABLE KEYS;


-- 2.6k

ALTER TABLE `patients` ENABLE KEYS;
UNLOCK TABLES;

SET FOREIGN_KEY_CHECKS = 1;
